#!/usr/bin/env node
// Idempotent fixture seeder for the beads-viewer behavioral E2E suite.
//
// Phase T2 (ka-0000006317) of epic ka-0000004611.
//
// Strategy (matches plan of record `gardenio/plans/beads-viewer-playwright-tests.md`):
//
//   1. The viewer talks to a real beads daemon. We do NOT fake the wire
//      protocol — that protocol is part of what the suite tests.
//   2. Bead ids are auto-generated by the daemon (`kd-` + nanoid), so
//      "pinned ids per type" cannot mean hard-coded ids. Instead, each
//      fixture is identified by a stable **label** (`fixture:e2e:<key>`)
//      and the seed script resolves the label → id once and writes a
//      manifest (`fixtures/ids.json`) that the test files load.
//   3. Re-running the seed is a no-op when the labelled fixture already
//      exists — same id is returned. This is what gives the suite
//      "stable ids across runs" against the same daemon.
//
// What the script does, in order:
//
//   a. For each entry in `TYPE_CONFIGS` (e.g. `type:mr`), PUT the
//      type config if missing. Built-in daemon types (schedule, agent,
//      advice, decision, formula, task) need no registration; only
//      gardenio-controller-registered customs (`mr`) do.
//   b. For each entry in `FIXTURES`, look up `fixture:e2e:<key>`. If
//      present, reuse the id; if absent, create the bead with the
//      label + seed fields.
//   c. Write `fixtures/ids.json` (`{ "<key>": "kd-...", ... }`) plus
//      a tiny `fixtures/manifest.json` carrying daemon URL + iso
//      timestamp for debugging stale-manifest situations.
//
// Required env:
//   BEADS_HTTP_ADDR   — daemon HTTP endpoint (defaults to
//                       http://localhost:8080, matching the harness).
//
// Why a Node script (and not Go): keeps the test sub-tree pure JS so
// `npm install && npm test` works on a clean checkout without a Go
// toolchain. The script shells out to `kd` which is already on $PATH
// for any agent / dev environment that runs the e2e suite.

import { execFileSync } from 'node:child_process';
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { FIXTURE_LABEL_PREFIX, FIXTURES, TYPE_CONFIGS } from './fixtures.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));
const fixturesDir = resolve(__dirname, '..', 'fixtures');
const idsPath = resolve(fixturesDir, 'ids.json');
const manifestPath = resolve(fixturesDir, 'manifest.json');

const beadsHTTPAddr = process.env.BEADS_HTTP_ADDR || 'http://localhost:8080';

// Run kd with a stable env: agent pods inject BEADS_HTTP_ADDR, but local
// dev usually relies on the kd default of localhost:8080 — pass it
// explicitly so behavior is identical in both shells.
function kd(args, opts = {}) {
  const env = { ...process.env, BEADS_HTTP_ADDR: beadsHTTPAddr };
  try {
    return execFileSync('kd', args, {
      env,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
      ...opts,
    });
  } catch (err) {
    const stderr = err.stderr ? err.stderr.toString() : '';
    // Trim kd's usage banner — it dwarfs the one-line error.
    const firstLine = stderr.split('\n').find((l) => l.trim().length > 0) || err.message;
    throw new Error(`kd ${args.join(' ')} failed (exit ${err.status}): ${firstLine}`);
  }
}

function kdJSON(args, opts) {
  const out = kd([...args, '--json'], opts);
  // Some kd subcommands print a deprecation banner before the JSON
  // payload; strip everything before the first `{` or `[`.
  const trimmed = stripPreamble(out);
  return JSON.parse(trimmed);
}

function stripPreamble(s) {
  const i = s.search(/[{\[]/);
  return i === -1 ? s : s.slice(i);
}

function ensureTypeConfig({ key, value }) {
  // `kd config get` exits non-zero when the key is missing.
  try {
    kdJSON(['config', 'get', key]);
    return { action: 'reused', key };
  } catch {
    kd(['config', 'create', key, JSON.stringify(value)]);
    return { action: 'created', key };
  }
}

function findFixtureByLabel(key) {
  const label = FIXTURE_LABEL_PREFIX + key;
  // `--all-types` so config/data-kind beads (formula, advice, schedule)
  // are not filtered out by the default issue-only behaviour.
  const beads = kdJSON([
    'list',
    '--label',
    label,
    '--all-types',
    '--limit',
    '5',
  ]);
  if (!Array.isArray(beads) || beads.length === 0) return null;
  if (beads.length > 1) {
    // Multiple beads share the fixture label — clearest signal someone
    // ran the seed against two different projects on the same daemon.
    // Return the oldest so behaviour is deterministic; warn loudly.
    console.warn(
      `[seed] WARNING: ${beads.length} beads carry label ${label}. ` +
        `Using oldest (${beads[0].id}). Delete extras to silence this.`,
    );
  }
  return beads[0];
}

// fieldArg renders one `name=value` for `kd --field`. A leading '@' in the
// value is kd's "read value verbatim from file" sigil (key=@file / key=@-,
// ka-0000002135); a literal value that begins with '@' must be escaped as
// '@@' (resolveFieldValue in kbeads/cmd/kd/fields.go). Fixture values like
// `cron=@hourly` are literals, not file refs — without escaping, kd tries to
// open a file named `hourly` and the seed aborts, reddening test-beads-viewer-e2e
// on every MR regardless of diff (ka-0000004694).
function fieldArg(name, val) {
  const s = String(val);
  return `${name}=${s.startsWith('@') ? '@' + s : s}`;
}

function createFixture(spec) {
  const args = ['create', spec.title, '--type', spec.type, '--label', FIXTURE_LABEL_PREFIX + spec.key];
  // `operatedBy` attributes the create to a SPECIFIC human operator instead of
  // the seed's global BEADS_OPERATED_BY (oidc:e2e-fixture@example.com). The
  // daemon lazily provisions an operators row + canonical slug on this first
  // attributed write, which is the ONLY way to get a human directory row on
  // /people (ka-0000003378): the default e2e-fixture identity is screened OUT
  // of /people by the daemon's fixture-domain marker (kbeads http_operators.go
  // botOperatorMarkerRe matches @example.com), so a directory-visible operator
  // MUST be provisioned on a non-fixture domain (@example.test) via this flag.
  // Only meaningful at CREATE time — the daemon provisions on the write, not on
  // later updates — so re-runs (which take the reuse path) keep the operator
  // the first create established.
  if (spec.operatedBy) {
    args.push('--operated-by', spec.operatedBy);
  }
  // `assignee` sets the bead's assignee COLUMN. The bidirectional inbox's
  // agent→user MAIL population lists `type=mail` addressed to one of the
  // operator's recipient handles via the daemon's `assignee = ANY($::text[])`
  // predicate (client OperatedByID/Assignees → ?assignee_in=; user_inbox.go
  // recipientHandlesForOperator + ListBeadsFiltered). A seeded mail fixture must
  // therefore carry the operator's slug in its assignee column so it lands in
  // that operator's inbox — this flag is what puts it there. ka-0000002598.
  if (spec.assignee) {
    args.push('--assignee', spec.assignee);
  }
  if (spec.description) {
    args.push('--description', spec.description);
  }
  if (spec.role) {
    args.push('--role', spec.role);
  }
  if (spec.priority !== undefined && spec.priority !== null) {
    args.push('--priority', String(spec.priority));
  }
  for (const label of spec.extraLabels || []) {
    args.push('--label', label);
  }
  for (const [name, val] of spec.fields || []) {
    args.push('--field', fieldArg(name, val));
  }
  const bead = kdJSON(args);
  if (!bead.id) {
    throw new Error(`kd create returned no id for fixture ${spec.key}: ${JSON.stringify(bead)}`);
  }
  return bead;
}

function updateFixture(id, spec) {
  // Re-apply description + fields on every seed run so spec changes in
  // fixtures.mjs propagate to existing labelled beads. Without this,
  // changing a fixture's fields requires manually deleting the bead —
  // a footgun we hit when extending fixtures for T5 (gd-mBAiw7o92M).
  const args = ['update', id];
  if (spec.description) {
    args.push('--description', spec.description);
  }
  for (const [name, val] of spec.fields || []) {
    args.push('--field', fieldArg(name, val));
  }
  if (args.length > 2) {
    kd(args);
  }
}

function ensureFixture(spec) {
  const existing = findFixtureByLabel(spec.key);
  if (existing) {
    // TYPE-DRIFT RECOVERY (gd-PUe0plpV8u). A bead's TYPE cannot be migrated in
    // place — `kd update` has no `--type`, and each type has its OWN field
    // schema. So when a fixture's `type` changes in fixtures.mjs (e.g. the `mr`
    // fixture went type:mr → type:merge-request in gd-zObJFqI6bz, renaming its
    // pipeline field pipeline_status → mr_pipeline_status), a bead created by an
    // OLDER seed keeps the OLD type. The reuse path below would then write the
    // NEW type's fields onto the OLD-typed bead and the daemon 400s on the
    // unknown field ("mr_pipeline_status: unknown field") — aborting the ENTIRE
    // seed in globalSetup, so zero tests run.
    //
    // This only bites LONG-LIVED daemons that still carry the pre-migration
    // bead (a local dev / agent port-forwarded to the shared gardenio daemon);
    // hermetic CI spins up a fresh daemon and creates the bead at the CURRENT
    // type every run, which is exactly the local-broken / CI-green asymmetry
    // the bug reports. Renaming the seed's write back to the old field name is
    // the INVERSE fix — it would green the stale local daemon but 400 fresh CI,
    // because type:merge-request rejects pipeline_status.
    //
    // Recover generically (covers any future fixture type migration): DETACH the
    // fixture label from the drifted bead so this lookup stops resolving to it,
    // then fall through to create a correctly-typed replacement. The orphaned
    // bead is left in place (never deleted) — harmless on a shared daemon, and
    // it drops out of the fixture set the moment it no longer carries the label.
    if (existing.type && spec.type && existing.type !== spec.type) {
      const label = FIXTURE_LABEL_PREFIX + spec.key;
      kd(['label', 'remove', existing.id, label]);
      console.warn(
        `[seed] WARNING: fixture ${spec.key} exists as type=${existing.type} ` +
          `but the spec is now type=${spec.type}; detached ${label} from ` +
          `${existing.id} and recreating (a bead's type cannot be migrated ` +
          `in place).`,
      );
      const bead = createFixture(spec);
      return { action: 'recreated', id: bead.id, key: spec.key };
    }
    updateFixture(existing.id, spec);
    return { action: 'reused', id: existing.id, key: spec.key };
  }
  const bead = createFixture(spec);
  return { action: 'created', id: bead.id, key: spec.key };
}

function main() {
  console.log(`[seed] daemon: ${beadsHTTPAddr}`);

  for (const tc of TYPE_CONFIGS) {
    const r = ensureTypeConfig(tc);
    console.log(`[seed] type-config ${r.action}: ${r.key}`);
  }

  const ids = {};
  for (const spec of FIXTURES) {
    const r = ensureFixture(spec);
    ids[spec.key] = r.id;
    console.log(`[seed] fixture  ${r.action.padEnd(7)}: ${spec.key.padEnd(9)} → ${r.id}`);
  }

  // gd-98ZHVK6FgI: wire dependencies declared via `dependsOn: [...]` on
  // fixture specs. `kd dep add` is idempotent at the daemon level (a
  // duplicate edge returns a "already exists" error which we swallow) so
  // re-running the seed is safe. We resolve fixture keys → ids via the
  // manifest we just built so callers can refer to siblings symbolically.
  for (const spec of FIXTURES) {
    if (!spec.dependsOn || spec.dependsOn.length === 0) continue;
    const fromID = ids[spec.key];
    if (!fromID) continue;
    for (const entry of spec.dependsOn) {
      // Entry may be a plain string (key, default `blocks` type) or
      // `{ key, type }` to declare a typed edge (e.g. parent-child for
      // bundle docs — gd-YWlIKIwzXV: bundle reader walks the `deps`
      // table, so typed mentions alone are not enough).
      const targetKey = typeof entry === 'string' ? entry : entry.key;
      const depType = typeof entry === 'string' ? null : entry.type;
      const toID = ids[targetKey];
      if (!toID) {
        throw new Error(
          `fixture ${spec.key} dependsOn ${targetKey} but ${targetKey} is not in the manifest`,
        );
      }
      const args = ['dep', 'add', fromID, toID];
      if (depType) args.push('--type', depType);
      const label = depType ? `${targetKey} (${depType})` : targetKey;
      try {
        kd(args);
        console.log(`[seed] dep      created: ${spec.key} → ${label}`);
      } catch (err) {
        // Re-runs hit the "already exists" path in kbeads. Anything else
        // is a real error worth surfacing.
        const msg = String(err.message || '');
        if (/already exists|duplicate/i.test(msg)) {
          console.log(`[seed] dep      reused : ${spec.key} → ${label}`);
        } else {
          throw err;
        }
      }
    }
  }

  // ka-0000006319: resolve typed-mention placeholders. Some fixtures
  // need a typed `parent(gd-XXX)` mention in their description, but the
  // referenced id is unknown until the target fixture is seeded. The
  // fixture spec carries placeholder tokens (e.g. `__incident_intake__`)
  // which we replace with the resolved id, then `kd update` the
  // description so the daemon's reference extractor records the typed
  // edge. Re-runs are idempotent: replacing an already-resolved id with
  // the same id yields the same description, and `kd update` no-ops on
  // unchanged values.
  for (const spec of FIXTURES) {
    if (!spec.typedMentionPlaceholders || spec.typedMentionPlaceholders.length === 0) continue;
    const fromID = ids[spec.key];
    if (!fromID) continue;
    let resolved = spec.description || '';
    for (const { token, fixtureKey } of spec.typedMentionPlaceholders) {
      const targetID = ids[fixtureKey];
      if (!targetID) {
        throw new Error(
          `fixture ${spec.key} placeholder ${token} → ${fixtureKey} but ${fixtureKey} is not in the manifest`,
        );
      }
      resolved = resolved.split(token).join(targetID);
    }
    kd(['update', fromID, '--description', resolved]);
    console.log(`[seed] mentions resolved: ${spec.key} → typed parent(...)`);
  }

  // gd-DkG9VPzBgX: resolve `fieldRefs` — custom fields whose VALUE is a sibling
  // fixture's id, unknown until the whole table is seeded. The gardener-page
  // iterations wire `schedule_id` (→ the gardener bead) and
  // `schedule_prior_agent_id` (→ the previous iteration) this way so the
  // daemon-indexed FK lookup + causal chain ordering resolve to real ids.
  // `kd update --field` no-ops on an unchanged value, so re-runs are idempotent.
  for (const spec of FIXTURES) {
    if (!spec.fieldRefs || spec.fieldRefs.length === 0) continue;
    const fromID = ids[spec.key];
    if (!fromID) continue;
    const args = ['update', fromID];
    for (const { field, fixtureKey } of spec.fieldRefs) {
      const targetID = ids[fixtureKey];
      if (!targetID) {
        throw new Error(
          `fixture ${spec.key} fieldRef ${field} → ${fixtureKey} but ${fixtureKey} is not in the manifest`,
        );
      }
      args.push('--field', fieldArg(field, targetID));
    }
    kd(args);
    console.log(`[seed] fieldRefs resolved: ${spec.key} → ${spec.fieldRefs.map((r) => r.field).join(', ')}`);
  }

  // 4b (gd-QmNG6n3Fe6): resolve `gardenerEpicLabelRef` — a gardener trigger fixture
  // must carry the `gardener-epic:<plan-id>` label (gardenerEpicLabelFor) so
  // planGardener() resolves it as the plan's bound gardener, but the plan epic id
  // is unknown until the whole table is seeded (same late-binding problem as
  // fieldRefs, but for a LABEL not a field). `kd label add` is idempotent on the
  // daemon side, so re-runs no-op.
  for (const spec of FIXTURES) {
    if (!spec.gardenerEpicLabelRef) continue;
    const fromID = ids[spec.key];
    if (!fromID) continue;
    const targetID = ids[spec.gardenerEpicLabelRef];
    if (!targetID) {
      throw new Error(
        `fixture ${spec.key} gardenerEpicLabelRef → ${spec.gardenerEpicLabelRef} but that key is not in the manifest`,
      );
    }
    const label = `gardener-epic:${targetID}`;
    try {
      kd(['label', 'add', fromID, label]);
      console.log(`[seed] gardener-epic label: ${spec.key} → ${label}`);
    } catch (err) {
      const msg = String(err.message || '');
      if (/already|duplicate|exists/i.test(msg)) {
        console.log(`[seed] gardener-epic label reused: ${spec.key} → ${label}`);
      } else {
        throw err;
      }
    }
  }

  // Apply a non-default status to fixtures flagged `statusAfterSeed` (e.g. the
  // maps in-progress task, which must actually be status=in_progress so the
  // status chip strip renders an `in_progress` facet for the filter spec).
  // Idempotent: setting the same status twice is a no-op on the daemon side.
  //
  // kind=issue beads enforce an in_progress→assignee invariant (kbeads commit
  // e8d7f47cb / ka-0000006063): a bare `--status in_progress` is rejected with
  // HTTP 400 unless the bead already carries an assignee. Set the assignee in
  // the SAME update so the transition is legal — defaulting to a stable
  // synthetic e2e assignee when the fixture does not name one.
  const E2E_DEFAULT_ASSIGNEE = 'e2e-seed';
  for (const spec of FIXTURES) {
    if (!spec.statusAfterSeed) continue;
    const id = ids[spec.key];
    if (!id) continue;
    const args = ['update', id, '--status', spec.statusAfterSeed];
    if (spec.statusAfterSeed === 'in_progress') {
      args.push('--assignee', spec.assigneeAfterSeed || E2E_DEFAULT_ASSIGNEE);
    }
    kd(args);
    console.log(`[seed] status   ${spec.key.padEnd(9)} → ${id} (${spec.statusAfterSeed})`);
  }

  // gd-DkG9VPzBgX: close fixtures flagged `closeAfterSeed`. Gardener-page
  // iterations must be terminal (status=closed) so the iteration cards render
  // wrapup-derived outcomes + exit chips — a live run carries no wrap-up yet.
  // `kd close` errors on an already-closed bead; swallow that so re-runs are
  // idempotent. Runs LAST so the field/mention updates above (which target open
  // beads) are not blocked by closure.
  for (const spec of FIXTURES) {
    if (!spec.closeAfterSeed) continue;
    const id = ids[spec.key];
    if (!id) continue;
    try {
      kd(['close', id]);
      console.log(`[seed] closed   ${spec.key.padEnd(9)} → ${id}`);
    } catch (err) {
      const msg = String(err.message || '');
      if (/already closed|closed|not open/i.test(msg)) {
        console.log(`[seed] closed   reused : ${spec.key.padEnd(9)} → ${id}`);
      } else {
        throw err;
      }
    }
  }

  mkdirSync(fixturesDir, { recursive: true });
  writeFileSync(idsPath, JSON.stringify(ids, null, 2) + '\n');
  writeFileSync(
    manifestPath,
    JSON.stringify(
      {
        daemon: beadsHTTPAddr,
        seeded_at: new Date().toISOString(),
        fixture_label_prefix: FIXTURE_LABEL_PREFIX,
        keys: Object.keys(ids).sort(),
      },
      null,
      2,
    ) + '\n',
  );
  console.log(`[seed] wrote ${idsPath}`);
}

main();
